def shutdown(self):
    exception: Optional[Exception] = None
    for c in self._connectors:
        try:
            c.shutdown()
        except Exception as e:
            logger.exception("Exception during connector %s shutdown.", c.__class__.__name__)
            exception = e
    if exception:
        raise exception

